// Generated by node build.js.
(() => {
function calculate({pepe = 1, rabbit = 1, silver = 1, m3 = 1} = {}) {
  if (![1, 2].includes(pepe) || ![rabbit, silver, m3].every(v => [0, 1, 2].includes(v))) throw new RangeError('无效的角色状态');
  const base = pepe * 9;
  const bonus = silver * 75 + m3 * 30;
  // 使用整数百分数，避免浮点误差影响向下取整。
  const limit = Math.floor(base * (100 + bonus) / 100);
  const triggers = Math.ceil(limit / pepe);
  const extra = rabbit * triggers;
  const last = limit - (triggers - 1) * pepe;
  return {base, bonus, limit, triggers, extra, last, total: limit + extra, normal: pepe + rabbit, final: last + rabbit, efficiency: (limit + extra) / 9};
}

function combinations() {
  const rows = [];
  for (let rabbit = 0; rabbit < 3; rabbit++) for (let silver = 0; silver < 3; silver++) for (let m3 = 0; m3 < 3; m3++) {
    const team = {rabbit, silver, m3};
    rows.push({...team, ordinary: calculate({...team, pepe: 1}).total, elite: calculate({...team, pepe: 2}).total});
  }
  return rows;
}


const state = {pepe: 1, rabbit: 1, silver: 1, m3: 1};
const characters = [
  {id:'pepe',name:'佩佩',icon:'佩',role:'核心',info:['','每次 +1 · 基础上限 9','每次 +2 · 基础上限 18']},
  {id:'rabbit',name:'奶兔',icon:'兔',role:'额外叠层',info:['不上场','每次触发额外 +1 层','每次触发额外 +2 层']},
  {id:'silver',name:'银灰',icon:'银',role:'上限加成',info:['不上场','佩佩叠层上限 +75%','佩佩叠层上限 +150%']},
  {id:'m3',name:'M3',icon:'M',role:'上限加成',info:['不上场','佩佩叠层上限 +30%','佩佩叠层上限 +60%']}
];
const labels = ['不上场','普通','精锐'];
const el = id => document.getElementById(id);
const set = (id,value) => { el(id).textContent = value; };
el('characters').innerHTML = characters.map(c => `<div class="character"><div class="identity"><span class="avatar ${c.id}" aria-hidden="true">${c.icon}</span><div><h3>${c.name}<span class="role">${c.role}</span></h3><p id="${c.id}-info"></p></div></div><div class="segmented" role="group" aria-label="${c.name}状态">${(c.id === 'pepe' ? [1,2] : [0,1,2]).map(v => `<button type="button" data-character="${c.id}" data-value="${v}" aria-pressed="false">${labels[v]}</button>`).join('')}</div></div>`).join('');
const rows = combinations();
el('all-rows').innerHTML = rows.map((r,i) => `<tr data-row="${i}"><td>${['佩佩', ...characters.slice(1).filter(c => r[c.id]).map(c => c.name)].join('＋')}</td><td>${labels[r.rabbit].replace('不上场','—')}</td><td>${labels[r.silver].replace('不上场','—')}</td><td>${labels[r.m3].replace('不上场','—')}</td><td>${r.ordinary}</td><td>${r.elite}</td></tr>`).join('');
function render() {
  const r = calculate(state);
  document.querySelectorAll('[data-character]').forEach(b => b.setAttribute('aria-pressed', String(state[b.dataset.character] === Number(b.dataset.value))));
  characters.forEach(c => set(`${c.id}-info`, c.info[state[c.id]]));
  ['total','triggers','base','limit','normal','final'].forEach(key => set(key,r[key]));
  set('efficiency',r.efficiency.toFixed(2)); set('bonus-label',`+${r.bonus}%`); set('bonus-added',`+${r.limit-r.base}`); set('extra',`+${r.extra}`);
  [['base',r.base],['bonus',r.limit-r.base],['extra',r.extra]].forEach(([key,v]) => el(`${key}-bar`).style.width = `${v/r.total*100}%`);
  set('formula',`${r.limit} + ${state.rabbit} × ${r.triggers} = ${r.total}`);
  set('limit-formula',`佩佩上限 = ⌊${r.base} × (1 + ${state.silver*75}% + ${state.m3*30}%)⌋ = ${r.limit}；触发次数 = ⌈${r.limit} ÷ ${state.pepe}⌉ = ${r.triggers}`);
  set('last-note', r.last !== state.pepe ? `最后一次：佩佩 ${r.last} 层 ＋ 奶兔 ${state.rabbit} 层 = ${r.final} 层，奶兔完整触发。` : `每次触发：佩佩 ${state.pepe} 层 ＋ 奶兔 ${state.rabbit} 层`);
  document.querySelectorAll('[data-row]').forEach(tr => {const row=rows[Number(tr.dataset.row)];tr.classList.toggle('current',['rabbit','silver','m3'].every(k=>row[k]===state[k]));});
}
document.addEventListener('click', e => {
  const button = e.target.closest('button'); if (!button) return;
  if (button.dataset.character) {state[button.dataset.character]=Number(button.dataset.value); render();}
  if (button.dataset.preset || button.id === 'reset') {
    const preset=button.dataset.preset;
    Object.assign(state,preset==='elite'?{pepe:2,rabbit:2,silver:2,m3:2}:preset==='solo'?{pepe:1,rabbit:0,silver:0,m3:0}:{pepe:1,rabbit:1,silver:1,m3:1}); render();
  }
});
render();

const tabs = [...document.querySelectorAll('[role="tab"]')];
function selectTab(active) {
  for (const tab of tabs) {
    const selected = tab === active;
    tab.setAttribute('aria-selected', String(selected));
    tab.tabIndex = selected ? 0 : -1;
    el(tab.getAttribute('aria-controls')).hidden = !selected;
  }
}
tabs.forEach((tab, index) => {
  tab.addEventListener('click', () => selectTab(tab));
  tab.addEventListener('keydown', event => {
    const target = {ArrowRight: (index + 1) % tabs.length, ArrowLeft: (index + tabs.length - 1) % tabs.length, Home: 0, End: tabs.length - 1}[event.key];
    if (target === undefined) return;
    event.preventDefault();
    tabs[target].focus();
    selectTab(tabs[target]);
  });
});

const baseline = calculate().total;
function tableRow(cells) {
  return '<tr>' + cells.map(cell => '<td>' + cell + '</td>').join('') + '</tr>';
}
el('gain-rows').innerHTML = tableRow(['全员普通', baseline, '基准', '—']) + characters.map(character => {
  const total = calculate({[character.id]: 2}).total;
  const added = total - baseline;
  const percent = Number((100 * added / baseline).toFixed(2));
  return tableRow([character.name, total, '+' + added, percent + '%']);
}).join('');

const fullTeams = rows.filter(row => row.rabbit && row.silver && row.m3);
const byCount = Array.from({length: 5}, () => []);
for (const row of fullTeams) {
  for (const pepe of [1, 2]) {
    const team = {...row, pepe};
    const elites = characters.filter(character => team[character.id] === 2);
    byCount[elites.length].push({
      total: calculate(team).total,
      names: elites.map(character => character.name).join('＋') || '全员普通'
    });
  }
}
el('best-rows').innerHTML = byCount.map((teams, count) => {
  const highest = Math.max(...teams.map(team => team.total));
  const winners = teams.filter(team => team.total === highest);
  return tableRow([count + ' 张', highest, winners.map(team => team.names).join(' 或 ')]);
}).join('');

})();
